var builder = WebApplication.CreateBuilder(args);

// Cost-conscious choices:
// 1. Use built-in DI instead of expensive IoC containers
builder.Services.AddHttpClient();

// 2. Use IMemoryCache before adding Redis
builder.Services.AddMemoryCache();

// 3. Use free or low-cost observability
builder.Logging.AddConsole();

// 4. Health checks are free and essential
builder.Services.AddHealthChecks()
    .AddDbContextCheck<AppDbContext>();

var app = builder.Build();

app.MapHealthChecks("/health");
app.MapGet("/", () => "Running");

// Scale-out is a later decision, not an initial requirement
app.Run();
